return ['domain'=>'bulk-editor','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'pt_PT','project-id-version'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional 2.1.3','pot-creation-date'=>'2026-11-20T14:15:27+00:00','po-revision-date'=>'2026-11-20 15:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['WOLF - WordPress Posts Bulk Editor and Manager Professional'=>'WOLF - WordPress Posts Bulk Editor and Manager Professional','https://bulk-editor.pro/'=>'https://bulk-editor.pro/','Tools for managing and bulk edit posts, pages and all custom types data in the reliable and flexible way! Be professionals with managing data of your site!'=>'Ferramentas para gerir e editar em massa artigos, páginas e dados de todos os tipos de conteúdo personalizados, de forma fiável e flexível. Seja um profissional na gestão dos dados do seu site!','realmag777'=>'realmag777','https://pluginus.net/'=>'https://pluginus.net/','no rounding'=>'sem arredondamento','forbidden'=>'proibido','Default'=>'Predefinição','Checkboxes for the posts selection. Use SHIFT button on your keyboard to select multiple rows.'=>'Caixas de seleção dos artigos. Utilize a tecla SHIFT do teclado para selecionar várias linhas.','Thumbnail'=>'Miniatura','Title'=>'Título','Content'=>'Conteúdo','Excerpt'=>'Excerto','Slug'=>'Slug','Status'=>'Estado','Comment status'=>'Estado dos comentários','Can users comment post or not.'=>'Os utilizadores podem comentar o artigo ou não.','Open'=>'Aberto','Closed'=>'Fechado','Ping status'=>'Estado dos pings','A ping is a [this site has new content] notification that invites search engine bots to visit your blog.'=>'Um ping é uma notificação [este site tem novo conteúdo] que convida os robôs dos motores de pesquisa a visitar o seu blogue.','Send trackbacks to'=>'Enviar trackbacks para','Separate multiple URLs with spaces. Ping status should be open! Remove 2 links separated by space, save. After opening you will not see links as they had been pinged! No sense for roll back, its sending is instant. Trackbacks are a way to notify legacy blog systems that you’ve linked to them. If you link other WordPress sites, they’ll be notified automatically using pingbacks, no other action necessary. Do not use these fields for something else. They are parsed many times in core code (69 matches for to_ping); their format is fixed.'=>'Separe vários URL com espaços. O estado dos pings tem de estar aberto! Remova 2 ligações separadas por espaço e guarde. Depois de abrir, não verá as ligações, pois já foram notificadas! Não faz sentido reverter, o envio é instantâneo. Os trackbacks são uma forma de notificar sistemas de blogues antigos de que os ligou. Se ligar a outros sites WordPress, estes serão notificados automaticamente através de pingbacks, sem necessidade de mais nenhuma ação. Não utilize estes campos para outros fins. São analisados muitas vezes no código do núcleo (69 ocorrências de to_ping); o seu formato é fixo.','Post password'=>'Palavra-passe do artigo','Password for private posts'=>'Palavra-passe para artigos privados','Menu order'=>'Ordem no menu','Custom ordering position.'=>'Posição de ordenação personalizada.','Author'=>'Autor','Date Published'=>'Data de publicação','Date Published GMT'=>'Data de publicação GMT','Date modified'=>'Data de modificação','Date modified GMT'=>'Data de modificação GMT','Post parent'=>'Artigo superior','Post type'=>'Tipo de artigo','Post mime type'=>'Tipo MIME do artigo','Not in bulk edit as there is no built-uploader here, so no sense change mime type. Filtering only! The function is designed specifically for attached records.'=>'Não está na edição em massa, pois aqui não há carregador integrado, logo não faz sentido alterar o tipo MIME. Apenas para filtragem! A função destina-se especificamente a registos anexados.','Sticky'=>'Fixo','Stick this post to the front page'=>'Fixar este artigo na página inicial','Yes'=>'Sim','No'=>'Não','Default posts count per page'=>'Número predefinido de artigos por pá